"""
Depends on if your business is a sole proprietorship, single member LLC, multi member LLC, an LLC with the "S" tax election, an S Corporation, or a C Corporation.
"""

def sole_proprietorship():
    """Sole Proprietorship: All profits and losses pass to you individually. You're also personally liable for anything that goes wrong. Pro Tip: form an LLC or go get a free consultation with a business attorney."""
    return {"pass_individually": True, "personally_liable": True}

def single_member_llc():
    """Single Member LLC: Profits and losses pass through to you personally, but your liability is limited to the Company's assets. You also have to pay self employment tax."""
    return {"limited_liability": True, "self_employment_tax": True}

def multi_member_llc():
    """Multi-Member LLC: Profits and losses are split in proportion to each members ownership interest in the company. You also pay self employment tax."""
    return {"split_by_ownership": True, "self_employment_tax": True}

def llc_with_s_election():
    """LLC with "S" election: You pay yourself a reasonable salary, not subject to self employment tax. Remaining profits and losses pass through to shareholders in proportion to percentage interest in the corporation. Taxed distributions depend on basis, but this is where it gets complicated and I can't ELI5 (just let the CPA worry about this)."""
    return {"reasonable_salary": True, "no_self_employment_tax": True}

def s_corporation():
    """S Corporation: see above."""
    return llc_with_s_election()

def c_corporation():
    """C Corporation: The corporations profits are taxed at the corporate tax level and then any dividends made to shareholders are taxed as well. This is called double taxation and it's why C Corporations are not ideal for small business owners."""
    return {"double_taxation": True}

def unethical_life_pro_tip():
    """Unethical Life Pro Tip: Want to live a lavish lifestyle, completely tax free, and without much hard work!? Start a non-profit seed faith mega church, go on TV, and convince all the sheeple to send your church money, because god will take the little "seed of faith" they send and will "sow" the seed into 10x the amount they sent."""
    return {"lavish_lifestyle": True, "tax_free": True}

